import json

def recover_relations(response: str, atoms: dict[str, str]):
    relations = []

    # Cause-Effect relations
    if "cannot be squared with" in response:
        relations.append({"source": 1, "target": 2, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})

    # Evidence relations
    if "shows" in response or "indicates" in response or "confirms" in response:
        relations.append({"source": 5, "target": 1, "sense": "Evidence", "coupling": "entailment", "strength_band": "moderate"})

    # Restatement relations
    if "that is" in response or "in other words" in response:
        relations.append({"source": 2, "target": 3, "sense": "Restatement", "coupling": "equivalence", "strength_band": "weak"})

    # Refutation relations
    if "rules out" in response or "it cannot have, since" in response:
        relations.append({"source": 13, "target": 14, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"})

    # Contrast relations
    if "by contrast" in response or "whereas" in response or "but" in response:
        relations.append({"source": 1, "target": 3, "sense": "Contrast", "coupling": "none", "strength_band": "moderate"})

    # Concession relations
    if "although" in response or "despite" in response or "even though" in response:
        relations.append({"source": 9, "target": 10, "sense": "Concession", "coupling": "none", "strength_band": "weak"})

    # Alternative relations
    if "either" in response or "or" in response:
        relations.append({"source": 13, "target": 14, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"})

    # Disjunction relations
    if "at least one of" in response or "perhaps both" in response:
        relations.append({"source": 11, "target": 12, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "weak"})

    # Precedence relations
    if "before" in response or "after" in response:
        relations.append({"source": 11, "target": 14, "sense": "Precedence", "coupling": "none", "strength_band": "moderate"})

    # Succession relations
    if "led to" in response or "resulted in" in response:
        relations.append({"source": 7, "target": 8, "sense": "Succession", "coupling": "none", "strength_band": "weak"})

    return json.dumps(relations)

response = "Adjudicating between transmission and independent origin begins with the theoretical commitments that each side brings to the evidence. Diffusionism holds that cultural traits spread outward from a point of origin through contact, and Franz Boas emphasized detailed regional historical reconstruction over broad evolutionary schemes; a single radiating centre from which traits travel outward cannot be squared with the demand that each region's past be rebuilt from its own particular record. Set against that premise of spread from a single source, by contrast, stands the rival position that resemblance between distant societies need involve no contact whatever. Independent invention accounts explain cross-cultural similarities as separate responses to comparable conditions. Arbitrary non-functional details shared by two practices weigh against independent invention. That programme of close regional reconstruction led directly to the distributional test that still carries most of the argumentative weight: the presence of the trait in intervening regions supports a diffusion route between two distant societies, whereas an account resting on separate responses to similar conditions predicts no such intervening corridor of occurrences. The age-area hypothesis infers that a trait with a wide distribution is older than one with a narrow distribution. Radiocarbon dating establishes the chronological order in which a practice appears in each region. Radiocarbon dating measures the decay of potassium-40 in organic tissue, and it is this measurement that shows the order of first appearances region by region to be recoverable at all. Chronology alone, however, does not settle comparative inference, because the units entered into a comparison are rarely independent of one another. It was precisely Galton's problem, the statistical non-independence of cultures sampled in cross-cultural comparisons, that gave rise to phylogenetic comparative methods, which control for shared ancestry when testing correlations across cultures. Properly specified, such models hold apart resemblance inherited from a common ancestral culture, resemblance acquired through borrowing, and resemblance generated afresh. The Polynesian sweet potato is the case on which these considerations are most often exercised. Sweet potato remains excavated in the Cook Islands date to approximately 1000 CE. The sweet potato is native to Southeast Asia, and that provenance confirms that genomic analysis found no Native American ancestry in pre-contact Polynesian populations. That absence and the finding that genomic analysis identified Native American ancestry in Polynesian genomes dating to around 1200 CE cannot both hold, and exactly one of them must: either the pre-contact populations were genetically untouched by the Americas, or admixture was already present by the thirteenth century. The Cook Islands tubers, for their part, lay in the ground some two centuries before the genomes in which that ancestry appears."
atoms = {"1": "Diffusionism holds that cultural traits spread outward from a point of origin through contact.", "2": "Franz Boas emphasized detailed regional historical reconstruction over broad evolutionary schemes.", "3": "Independent invention accounts explain cross-cultural similarities as separate responses to comparable conditions.", "4": "Arbitrary non-functional details shared by two practices weigh against independent invention.", "5": "The presence of the trait in intervening regions supports a diffusion route between two distant societies.", "6": "The age-area hypothesis infers that a trait with a wide distribution is older than one with a narrow distribution.", "7": "Radiocarbon dating establishes the chronological order in which a practice appears in each region.", "8": "Radiocarbon dating measures the decay of potassium-40 in organic tissue.", "9": "Galton's problem is the statistical non-independence of cultures sampled in cross-cultural comparisons.", "10": "Phylogenetic comparative methods control for shared ancestry when testing correlations across cultures.", "11": "Sweet potato remains excavated in the Cook Islands date to approximately 1000 CE.", "12": "The sweet potato is native to Southeast Asia.", "13": "Genomic analysis found no Native American ancestry in pre-contact Polynesian populations.", "14": "Genomic analysis identified Native American ancestry in Polynesian genomes dating to around 1200 CE."}

print(recover_relations(response, atoms))
